loop {
    $n++;
    $sum += $n;
    last if $sum > 100;
}

say "reached $sum after adding 1..$n";

sub digit-sum($n) {
    return $n if $n < 10;
    return $n % 10 + digit-sum($n div 10);
}

say digit-sum(12345);

sub compose(&f, &g) {
    return -> $x { f(g($x)) };
}

my $combined = compose(* * 2, * + 1);

say $combined(5);

sub make-accumulator($start) {
    my $total = $start;
    return -> $amount { $total += $amount };
}

my $acc = make-accumulator(100);

say $acc(10);
say $acc(25);
say $acc(-5);

sub make-accumulator($start) {
    return -> $amount { state $total = $start; $total += $amount };
}

my $acc = make-accumulator(100);
say $acc(10);
say $acc(25);
say $acc(-5);

multi describe(Int $x) { "integer $x" }
multi describe(Str $x) { "string $x" }
